const { schemaVersion } = require('./control-type-contract.json')
const { runtimeJsonRequest } = require('./panel-http')
const { meterRoute } = require('./meter-route')
const { xySeriesRoute } = require('./xy-series-route')

function catalogBase (settings) {
  const port = Number(settings?.uiPort)
  const runtimeBase = settings?.httpAdminRoot !== false &&
    Number.isInteger(port) && port > 0 && port <= 65535
    ? `http://127.0.0.1:${port}${settings?.httpAdminRoot || '/'}` : ''
  const raw = process.env.CONTROL_PANEL_CATALOG_BASE_URL || runtimeBase
  if (!raw) return null
  const url = new URL(raw)
  if (url.protocol !== 'http:' || !['127.0.0.1', 'localhost'].includes(url.hostname) || url.username || url.password) {
    throw new Error('Catalog URL must be an unauthenticated localhost HTTP URL')
  }
  return url.href.endsWith('/') ? url.href : `${url.href}/`
}

async function catalogRequest (base, path, device, fetcher = fetch) {
  const options = {}
  if (device !== undefined) {
    options.method = 'POST'
    options.headers = { 'content-type': 'application/json' }
    options.body = JSON.stringify([device])
  }
  const { response, data } = await runtimeJsonRequest(new URL(path, base), options, {
    fetcher, timeoutMs: 15000, operation: `Device catalog ${path}${device ? ' (' + device + ')' : ''}`
  })
  if (!response.ok) throw new Error(`Automator catalog HTTP ${response.status}`)
  if (data.code !== 0 || !Array.isArray(data.value)) throw new Error(data.reason || 'Invalid Automator catalog response')
  return data.value
}

async function listCatalogDevices (base, fetcher = fetch) {
  const values = await catalogRequest(base, 'amx-com/devices', undefined, fetcher)
  return values.filter(item => typeof item.instanceId === 'string').map(item => ({
    id: item.instanceId,
    driver: item.driver?.driver || '',
    online: item.online === true
  }))
}

function catalogBound (value) {
  return typeof value === 'number' && Number.isFinite(value) &&
    Math.abs(value) < Number.MAX_SAFE_INTEGER ? value : undefined
}

function inferredControl (path, properties, type, min, max, enums) {
  if (properties['.kind'] !== 'param' || path.startsWith('//module/')) return { controlType: '' }
  if (type === 'boolean') return { controlType: 'toggle' }
  if (type === 'integer' && min === 0 && max === 1 && !enums?.length) {
    return { controlType: 'toggle', booleanEncoding: 'integer01' }
  }
  if (type === 'enum' || (enums?.length && ['integer', 'string'].includes(type))) {
    return { controlType: 'source' }
  }
  if (type === 'integer' && /\/(preset|source)$/.test(path.toLowerCase())) {
    return { controlType: 'source' }
  }
  if (['integer', 'float'].includes(type)) return { controlType: 'slider' }
  if (['string', 'dstring'].includes(type)) return { controlType: 'text' }
  return { controlType: '' }
}

async function listCatalogTargets (base, device, fetcher = fetch) {
  if (typeof device !== 'string' || !device || device.length > 128) throw new Error('Invalid device name')
  const [parameters, commands] = await Promise.all([
    catalogRequest(base, 'amx-com/device/status', device, fetcher),
    catalogRequest(base, 'amx-com/device/commands', device, fetcher)
  ])
  const targets = [...parameters, ...commands].filter(item => typeof item.path === 'string').map(item => {
    const properties = item.properties || {}
    const type = properties['.type'] || item.schema?.type || ''
    const min = catalogBound(properties['.min'])
    const max = catalogBound(properties['.max'])
    const enums = properties['.enums']
    const meter = properties['.metadata']?.meter ? meterRoute(properties['.metadata'].meter) : null
    const xySeries = properties['.metadata']?.xySeries ? xySeriesRoute(properties['.metadata'].xySeries) : null
    return {
      path: item.path,
      kind: properties['.kind'] || '',
      type,
      access: properties['.access'],
      onebased: typeof properties['.onebased'] === 'boolean' ? properties['.onebased']
        : typeof item.onebased === 'boolean' ? item.onebased : undefined,
      min, max, enums,
      ...(meter ? { controlType: 'meter' } : xySeries ? { controlType: 'xy-series' } : inferredControl(item.path, properties, type, min, max, enums)),
      controlSchemaVersion: schemaVersion,
      unit: properties['.metadata']?.unit || '',
      ...(meter ? { meter } : {}),
      ...(xySeries ? { xySeries } : {})
    }
  })
  const unique = new Map()
  for (const target of targets) {
    const previous = unique.get(target.path)
    if (previous && JSON.stringify(previous) !== JSON.stringify(target)) {
      throw new Error(`Conflicting catalog descriptors for ${target.path}`)
    }
    unique.set(target.path, target)
  }
  return [...unique.values()]
}

module.exports = { catalogBase, listCatalogDevices, listCatalogTargets }
